## Backend API (Express)

```js
// server.js
import express from 'express';
import crypto from 'crypto';
import { createClient } from '@supabase/supabase-js';

const app = express();
app.use(express.json());

const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_KEY);

// Anonymous sign-in: hash the device id, create or fetch user
app.post('/auth/anon', async (req, res) => {
  const { deviceId } = req.body;
  const device_hash = crypto.createHash('sha256').update(deviceId).digest('hex');

  const { data: existing } = await supabase
    .from('users').select('id').eq('device_hash', device_hash).maybeSingle();

  if (existing) return res.json({ userId: existing.id });

  const { data, error } = await supabase
    .from('users').insert({ device_hash }).select('id').single();
  if (error) return res.status(500).json({ error });
  res.json({ userId: data.id });
});

// Create a post
app.post('/posts', async (req, res) => {
  const { userId, body, imageUrl, ephemeral } = req.body;
  const expires_at = ephemeral ? new Date(Date.now() + 864e5) : null;

  const { data, error } = await supabase
    .from('posts').insert({ author_id: userId, body, image_url: imageUrl, expires_at })
    .select().single();
  if (error) return res.status(500).json({ error });
  res.json(data);
});

// Feed: sort by roast ratio, exclude expired
app.get('/feed', async (req, res) => {
  const { data, error } = await supabase
    .from('posts')
    .select('id, body, image_url, created_at, reactions(kind)')
    .eq('is_removed', false)
    .or(`expires_at.is.null,expires_at.gt.${new Date().toISOString()}`)
    .order('created_at', { ascending: false })
    .limit(50);
  if (error) return res.status(500).json({ error });

  const scored = data.map(p => {
    const roasts = p.reactions.filter(r => r.kind === 'roast').length;
    const boosts = p.reactions.filter(r => r.kind === 'boost').length;
    return { ...p, roasts, boosts, score: roasts - boosts };
  }).sort((a, b) => b.score - a.score);

  res.json(scored);
});

// React (boost or roast)
app.post('/react', async (req, res) => {
  const { userId, postId, kind } = req.body;
  const { error } = await supabase
    .from('reactions')
    .upsert({ user_id: userId, post_id: postId, kind }, { onConflict: 'post_id,user_id' });
  if (error) return res.status(500).json({ error });
  res.json({ ok: true });
});

// Report
app.post('/report', async (req, res) => {
  const { userId, postId, reason } = req.body;
  await supabase.from('reports').insert({ reporter_id: userId, post_id: postId, reason });
  res.json({ ok: true });
});

app.listen(3000, () => console.log('Roastr API on :3000'));
```

