## Frontend (React Native, key screens)

```jsx
// FeedScreen.js
import { useEffect, useState } from 'react';
import { View, Text, FlatList, TouchableOpacity, StyleSheet } from 'react-native';

export default function FeedScreen({ userId }) {
  const [posts, setPosts] = useState([]);

  useEffect(() => {
    fetch('http://localhost:3000/feed')
      .then(r => r.json())
      .then(setPosts);
  }, []);

  const react = async (postId, kind) => {
    await fetch('http://localhost:3000/react', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId, postId, kind }),
    });
    // optimistic update
    setPosts(prev => prev.map(p =>
      p.id === postId
        ? { ...p, [kind === 'roast' ? 'roasts' : 'boosts']: p[kind === 'roast' ? 'roasts' : 'boosts'] + 1 }
        : p
    ));
  };

  return (
    <FlatList
      data={posts}
      keyExtractor={p => p.id}
      renderItem={({ item }) => (
        <View style={styles.card}>
          <Text style={styles.body}>{item.body}</Text>
          <View style={styles.row}>
            <TouchableOpacity onPress={() => react(item.id, 'boost')}>
              <Text>🔥 Boost {item.boosts}</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={() => react(item.id, 'roast')}>
              <Text>💀 Roast {item.roasts}</Text>
            </TouchableOpacity>
          </View>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  card: { padding: 16, margin: 8, backgroundColor: '#1a1a1a', borderRadius: 12 },
  body: { color: '#fff', fontSize: 16 },
  row: { flexDirection: 'row', justifyContent: 'space-between', marginTop: 12 },
});
```

